 const pools=pairs.filter(x=>numeric(num(x.liquidity?.usd))&&num(x.liquidity.usd)>0),sum=pools.reduce((a,x)=>a+num(x.liquidity.usd),0),colors=['#b9694e','#a9967c','#7e9882','#c5b291','#9ba7a3','#d6cdc0'];if(sum>0){const top=pools.slice(0,4).map((x,i)=>({name:x.quoteToken?.symbol||'未知',address:x.pairAddress,val:num(x.liquidity.usd),color:colors[i]})),other=pools.slice(4).reduce((a,x)=>a+num(x.liquidity.usd),0);if(other>0)top.push({name:'其他 '+(pools.length-4)+' 个池',val:other,color:colors[4]});$('poolDistribution').innerHTML=`<div class="disttotal">${money(sum)}<small>已知池流动性估值合计</small></div><div class="diststack">${top.map(x=>`<div style="width:${x.val/sum*100}%;background:${x.color}" title="${esc(x.name)}：${(x.val/sum*100).toFixed(1)}%"></div>`).join('')}</div>${top.map(x=>`<div class="distrow"><i style="background:${x.color}"></i>${x.address?`<button data-dist-pool="${esc(x.address)}">${esc(x.name)} · ${esc(x.address.slice(0,6))}…${esc(x.address.slice(-4))}</button>`:`<span style="flex:1">${esc(x.name)}</span>`}<span class="distpct">${(x.val/sum*100).toFixed(1)}%</span><strong>${money(x.val)}</strong></div>`).join('')}`}else emptyViz('poolDistribution','缺少有效流动性估值');
