function drawIndexed(){const data=history.filter(s=>s.pool===selected&&numeric(s.price)&&s.price>0&&numeric(s.liquidity)&&s.liquidity>0).slice(-120);$('historyInfo').textContent=(storageAvailable?'当前浏览器':'本次会话')+' · '+data.length+' 个共同有效样本';$('chartLegend').innerHTML='<span><i style="background:#b9694e"></i>价格</span><span><i style="background:#7e9882"></i>流动性</span><span>首个可见共同样本 = 100</span>';if(data.length<2){emptyViz('chart','等待至少两次共同有效采样');return}const base=data[0],values=data.flatMap(d=>[d.price/base.price*100,d.liquidity/base.liquidity*100]),min=Math.min(100,...values),max=Math.max(100,...values),range=max-min||1,t0=base.t,dt=data.at(-1).t-t0||1,x=t=>48+(t-t0)/dt*500,y=v=>165-(v-min)/range*130;let chart='';[min,(min+max)/2,max].forEach(v=>{chart+=`<line x1="48" y1="${y(v)}" x2="548" y2="${y(v)}" stroke="#e7e2d7" stroke-dasharray="3 4"/><text x="0" y="${y(v)+4}" fill="#948d81" font-size="10">${v.toFixed(1)}</text>`});[['price','#b9694e','价格'],['liquidity','#7e9882','流动性']].forEach(([key,color,label])=>{let path='';data.forEach((d,i)=>path+=(i===0||d.t-data[i-1].t>300000?'M':'L')+x(d.t).toFixed(2)+','+y(d[key]/base[key]*100).toFixed(2)+' ');chart+=`<path d="${path}" fill="none" stroke="${color}" stroke-width="2"/>`+data.map(d=>`<circle cx="${x(d.t)}" cy="${y(d[key]/base[key]*100)}" r="2.5" fill="${color}"><title>${time(d.t)} ${label} ${money(d[key])} · 指数 ${(d[key]/base[key]*100).toFixed(2)}</title></circle>`).join('')});chart+=`<text x="48" y="204" font-size="10" fill="#948d81">${time(t0)}</text><text x="548" y="204" text-anchor="end" font-size="10" fill="#948d81">${time(data.at(-1).t)}</text>`;$('chart').innerHTML=svgWrap(chart,560,220,'价格与流动性指数对比，起点均为100');}
